// ===== À ADAPTER (dans n8n, pas dans Git) =====
const PLANE_PUBLIC_URL = 'https://plane.TON-DOMAINE'; // adresse de Plane, sans / final
const PLANE_PROJECT_ID = 'ID-DU-PROJET-PLANE';        // UUID du projet Plane Flowly
// ===============================================
const PLANE_API_URL = 'http://plane-app-api.plane.svc.cluster.local:8000';
const GITHUB_ORG = 'Flowly-PBS';

// Label Plane -> dépôt GitHub et projet GitHub (ID GraphQL du projet).
const EQUIPES = {
  frontend: { repo: 'Frontend', projet: 'PVT_kwDOD8weaM4Bjzd_' }, // projet 2
  backend:  { repo: 'Backend',  projet: 'PVT_kwDOD8weaM4Bjr2x' }, // projet 1
  mobile:   { repo: 'Mobile',   projet: 'PVT_kwDOD8weaM4BjzeI' }, // projet 3
  devops:   { repo: 'DevOps',   projet: 'PVT_kwDOD8weaM4BkSMk' }, // projet 5
};

const p = $('Webhook Plane').first().json.body || {};
const d = p.data || {};
const champ = (p.activity || {}).field;

// Seulement : un ticket créé, ou ses labels modifiés, dans le bon projet.
const cree = ['created', 'create'].includes(p.action);
const labelsModifies = ['updated', 'update'].includes(p.action)
  && ['label_ids', 'labels'].includes(champ);
if (p.event !== 'issue' || !(cree || labelsModifies)) return [];
if (d.project !== PLANE_PROJECT_ID || !d.id) return [];

const noms = new Set((d.labels || [])
  .map((l) => (l && typeof l === 'object' ? String(l.name || '') : ''))
  .map((n) => n.trim().toLowerCase()));

const slug = p.workspace_slug;
const lienPlane = `${PLANE_PUBLIC_URL}/${slug}/projects/${d.project}/issues/${d.id}`;
const texte = String(d.description_stripped || '').trim();
const corps = [
  texte || '_Pas de description dans Plane._',
  '',
  '---',
  `Ticket Plane : ${lienPlane}`,
  `<!-- plane-work-item: ${d.id} -->`,
].join('\n');

return Object.entries(EQUIPES)
  .filter(([label]) => noms.has(label))
  .map(([label, e]) => ({
    json: {
      plane_api: PLANE_API_URL,
      slug,
      project_id: d.project,
      issue_id: d.id,
      equipe: label,
      github_org: GITHUB_ORG,
      repo: e.repo,
      projet_github: e.projet,
      prefixe: `https://github.com/${GITHUB_ORG}/${e.repo}/issues/`,
      titre: String(d.name || 'Sans titre'),
      corps,
    },
  }));

// Garde une équipe seulement si le ticket Plane n'a pas
// déjà un lien vers une issue de son dépôt (pas de doublon).
const equipes = $('Équipes à traiter').all();
return $input.all().flatMap((reponse, i) => {
  const t = equipes[i].json;
  const liens = reponse.json.results || [];
  const existe = liens.some((l) => String(l.url || '').startsWith(t.prefixe));
  return existe ? [] : [{ json: t, pairedItem: { item: i } }];
});

// GraphQL répond 200 même en cas d'erreur : on la fait remonter.
if ($json.errors) {
  throw new Error('GitHub Projects : ' + JSON.stringify($json.errors));
}
return $input.item;
